            content = t[m.end():].split('\n')[:h]
            rows = [row.split() for row in content[:h]]
            if k not in G and len(rows) == h and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in row] for row in rows]
        return G
    except:
        return {}

G = load()
print("Keys found:", list(G.keys()))

G = load()
