            if msg_type == 'session':
                continue
            elif msg_type == 'model_change':
                continue
            elif msg_type == 'thinking_level_change':
                continue
            elif msg_type == 'message':
                msg = data.get('message', {})
                role = msg.get('role')
                content = msg.get('content', [])

                if role == 'user':
                    # Search in user messages for Demo pairs or grids
                    text = ''
                    for item in content:
                        if item.get('type') == 'text':
                            text += item.get('text', '')

                    # Find Demo pair grids
                    demo_pattern = r'Demo pair \d+ (?:input|output)\n([\d\s\n]+)'
                    for match in re.finditer(demo_pattern, text):
                        demo_text = match.group(1)
                        try:
                            # Parse the demo grid
                            demo_lines = demo_text.strip().split('\n')
                            # Skip the "Demo pair N input/output" lines
                            filtered_lines = [l for l in demo_lines if 'Demo pair' not in l]
                            if filtered_lines:
